import sys,re
lines=open('D:/the-synaptic-sea-2d/design/registry/entities.yaml',encoding='utf-8').read().split('\n')
starts=[i for i,l in enumerate(lines) if re.match(r'^  - name:',l)]
names={}
for k,i in enumerate(starts):
    n=lines[i].split('name:',1)[1].strip().strip('"\'')
    end=starts[k+1] if k+1<len(starts) else len(lines)
    # trim trailing section comment lines? keep
    names.setdefault(n,[]).append((i,end))
for q in sys.argv[1:]:
    if q=='--list':
        for n,r in names.items(): print(n,r[0][0]+1)
        continue
    hits=[n for n in names if n==q] or [n for n in names if q.lower() in n.lower()]
    if not hits: print('NOT FOUND',q); continue
    for n in hits:
        for (a,b) in names[n]:
            print(f'=== {n} lines {a+1}-{b}')
            for j in range(a,b): print(f'{j+1}: {lines[j]}')
EOF
python $S/show.py --list | wc -l; python $S/show.py restore_epoch SL_RESTORE_EPOCH_NOT_DURABLE state_hash

